import os
from flask import Flask, request, abort, send_file
from flask import secure_filename

app = Flask(__name__)
REPORTS = os.path.abspath("./data/reports")

# Define a function to validate and sanitize the filename
def validate_filename(filename):
    allowed_extensions = set(['txt', 'pdf', 'docx', 'xlsx'])
    if not filename:
        return False
    if not filename.lower().endswith(allowed_extensions):
        return False
    return True

@app.route("/download")
def download():
    filename = request.args.get("filename", "")
    if not filename:
        abort(400)
    if not validate_filename(filename):
        abort(400)
    path = os.path.join(REPORTS, filename)
    if not os.path.isfile(path):
        abort(404)
    return send_file(path, as_attachment=True, attachment_filename=secure_filename(filename))
