import base64
import pickle
import hashlib

def dump_cart(items):
    # Use a secure hash function to prevent tampering
    hash_value = hashlib.sha256(str(items).encode()).digest()
    return base64.b64encode(hash_value + pickle.dumps(items)).decode("ascii")

def restore_cart(cookie_value):
    # Verify the integrity of the cookie value
    expected_hash_value = hashlib.sha256(str(cookie_value).encode()).digest()
    if base64.b64decode(cookie_value) != expected_hash_value + pickle.loads(base64.b64decode(cookie_value)):
        raise ValueError("Cookie value is tampered with")

    return pickle.loads(base64.b64decode(cookie_value))
